/* pkgPWF (ASK 258): an E-ANS cure counts an [L1] only when the ANSWER (with the words its reason quotes) names that verse or quotes 2 of its words; an ANSWER naming no verse keeps every [L1]. */ function pwf(to,a){const m=to.match(AQ);if(!m)return null;const ans=m[1];if(!/\d{1,3}:\d{1,3}/.test(ans))return null;const T=ans+' '+((N(a&&a.why||'').match(/["“][^"”]{3,}["”]/g))||[]).join(' ');const rs=[...T.matchAll(/((?:[1-3] )?[A-Z][a-z]+(?: of [A-Z][a-z]+)? )?(\d{1,3}):(\d{1,3})(?:[-–](\d{1,3}))?/g)].map(x=>({b:x[1]?x[1].trim():null,c:+x[2],v1:+x[3],v2:+(x[4]||x[3])}));const W=s=>' '+String(s).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()+' ';const an=W(T);const FW=new Set('a an the of to in and or but is was be by for on at as that this it his her he she him i not with from which shall unto thee thou ye me my are were have hath s so there their they them also all no nor what who whom'.split(' '));const own=(b,c,v,q)=>{if(rs.some(r=>(!r.b||r.b===b)&&r.c===c&&v>=r.v1&&v<=r.v2))return true;const w=W(q).trim().split(' ');for(let i=0;i+1<w.length;i++)if(!(FW.has(w[i])&&FW.has(w[i+1]))&&an.includes(' '+w[i]+' '+w[i+1]+' '))return true;return false;};const R='((?:[1-3] )?[A-Z][a-z]+(?: of [A-Z][a-z]+)?) (\\d{1,3}):(\\d{1,3})(?:[-–]\\d{1,3})?';let t=N(m[3]||'');t=t.replace(new RegExp('\\[L1\\](\\s*)'+R+'([^"“”\\n\\[]{0,40}?)["“‘\']([^"“”’]{6,400}?)["”’\']','g'),(s,sp,b,c,v,mid,q)=>own(b,+c,+v,q)?s:'[L-]'+s.slice(4));t=t.replace(new RegExp(R+'([^"“”\\n\\[]{0,40}?)["“‘\']([^"“”’]{6,400}?)["”’\']([\\s;,.:)]*)\\[L1\\]','g'),(s,b,c,v,mid,q)=>own(b,+c,+v,q)?s:s.slice(0,-4)+'[L-]');return m[1]+' || '+t;}
